SELECT p.gender, p.age, s.admission_type_id, s.discharge_location_id, p.dod, AVG(s.los) AS average_los, MEDIAN(s.los) AS median_los, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY s.los) AS p75_los, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY s.los) AS p90_los, PERCENT_RANK() OVER (ORDER BY s.los) AS percentile_rank_within_10_days FROM patients p JOIN admissions s ON p.subject_id = s.subject_id WHERE p.gender = 'M' AND p.age BETWEEN 62 AND 67 AND s.admission_type_id = 1 AND s.discharge_location_id IN (1001, 1002) AND s.discharge_time IS NOT NULL AND (s.discharge_time - s.admittime) > 10 GROUP BY p.gender, p.age, s.admission_type_id, s.discharge_location_id, p.dod ORDER BY p.gender, p.age, s.admission_type_id, s.discharge_location_id, p.dod NULLS LAST;